insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_71_v1'
from (values
('127.481.d.1.A',3,'A student dissecting a preserved heart wonders why the left wall is thicker than the right. Forming this kind of puzzle from an observation is:','["asking a scientific question", "buying supplies", "filing a report", "ending the lab"]'::jsonb,0,'Observation leads to questions.','original'),
('127.481.d.1.A',4,'Before testing how exercise affects pulse, an anatomy class states exactly what is being studied and what will be measured. This step is:','["grading the lab", "defining the problem", "choosing lunch", "cleaning glassware"]'::jsonb,1,'A defined problem guides the plan.','original'),
('127.481.d.1.B',3,'To test how posture affects heart rate, a class changes only posture and keeps age, activity, and timing the same. This design is a:','["drawing", "guess", "controlled investigation", "random survey"]'::jsonb,2,'Only one variable changes.','original'),
('127.481.d.1.B',4,'Measuring pulse before and after jumping jacks on the same students is a comparative design because it compares:','["two textbooks", "two classrooms only", "two teachers", "two conditions"]'::jsonb,3,'Before and after conditions are compared.','original'),
('127.481.d.1.C',3,'During a dissection lab, students should wear gloves, goggles, and:','["a lab apron", "a scarf", "earbuds", "sandals"]'::jsonb,0,'PPE protects skin and clothes.','original'),
('127.481.d.1.C',4,'After a dissection, the safest way to handle used scalpels is to place them in a:','["desk drawer", "designated sharps container", "trash can", "backpack"]'::jsonb,1,'Sharps need special disposal.','original'),
('127.481.d.1.D',3,'A blood pressure cuff and a stethoscope are tools used in an anatomy lab to measure:','["bone color", "tissue stains", "vital signs", "muscle names"]'::jsonb,2,'They measure cardiovascular function.','original'),
('127.481.d.1.D',4,'Using a goniometer to measure the angle of a joint is an example of choosing a tool for an anatomy lab:','["recipe", "bus schedule", "budget", "measurement"]'::jsonb,3,'Tools match measurements.','original'),
('127.481.d.1.E',3,'In SI units, a student''s height is best recorded in:','["centimeters", "inches", "feet", "yards"]'::jsonb,0,'SI length units are metric.','original'),
('127.481.d.1.E',4,'A resting pulse is recorded as 72 beats in 60 seconds. In SI-friendly units, this is 72 beats per:','["week", "minute", "hour", "day"]'::jsonb,1,'Time unit is minutes.','original'),
('127.481.d.1.F',3,'Students record resting heart rates in a table so the data can be compared. This is organizing:','["stories only", "rumors", "quantitative data", "opinions only"]'::jsonb,2,'Numbers are quantitative.','original'),
('127.481.d.1.F',4,'A lab report with a labeled bar graph of pulse before and after exercise is an example of organizing data with a:','["secret", "menu", "rumor", "visual display"]'::jsonb,3,'Graphs display data.','original'),
('127.481.d.1.G',3,'A plastic torso with removable organs helps students study the body by serving as a:','["model", "receipt", "recipe", "badge"]'::jsonb,0,'Models represent anatomy.','original'),
('127.481.d.1.G',4,'A flowchart showing how a nerve signal travels to a muscle is a model of a:','["country", "process", "holiday", "building"]'::jsonb,1,'Models represent processes.','original'),
('127.481.d.1.H',3,'The idea that all living things are made of cells is supported by countless observations. In science, such a well-supported explanation is called a:','["guess", "opinion", "theory", "hunch"]'::jsonb,2,'Theories are well supported.','original'),
('127.481.d.1.H',4,'A testable prediction such as exercise will raise the pulse is a:','["theory", "law", "fact", "hypothesis"]'::jsonb,3,'Hypotheses are testable predictions.','original'),
('127.481.d.2.A',3,'A plastic model of the skeleton is helpful but cannot show how bones:','["grow and heal", "are named", "look", "are shaped"]'::jsonb,0,'Models have limits.','original'),
('127.481.d.2.A',4,'A model of the lungs made with a bottle and balloons shows how air moves but not the actual:','["shape of a room", "gas exchange in alveoli", "size of the bottle", "color of balloons"]'::jsonb,1,'Models simplify.','original'),
('127.481.d.2.B',3,'A student sees that resting pulse is lower in students who exercise more often. She has identified a:','["mistake", "label", "pattern", "tool"]'::jsonb,2,'Patterns appear in data.','original'),
('127.481.d.2.B',4,'A scientist averages the pulse rates of 30 students to describe the class. The average is a statistical:','["law", "error", "hypothesis", "feature of the data"]'::jsonb,3,'Mean is a statistic.','original'),
('127.481.d.2.C',3,'Cardiac output equals heart rate times stroke volume. A heart that beats 70 times a minute with 70 mL per beat pumps:','["4,900 mL per minute", "490 mL per minute", "140 mL per minute", "49 mL per minute"]'::jsonb,0,'70 x 70 = 4,900.','original'),
('127.481.d.2.C',4,'If a student breathes 12 times a minute and moves 500 mL of air each breath, minute ventilation is:','["600 mL", "6,000 mL", "60,000 mL", "512 mL"]'::jsonb,1,'12 x 500 = 6,000.','original'),
('127.481.d.2.D',3,'Judging whether a wearable heart monitor is accurate and meets its goals is evaluating the:','["price tag only", "color", "design", "name"]'::jsonb,2,'Evaluate designs against goals.','original'),
('127.481.d.2.D',4,'Engineers testing an artificial joint check strength, safety, and fit. They are evaluating an engineering:','["logo", "rumor", "opinion", "design"]'::jsonb,3,'Designs are evaluated.','original'),
('127.481.d.3.A',3,'A student claims that fluid intake raises urine output and supports the claim with measured data. This is an explanation backed by:','["evidence", "luck", "gossip", "opinion"]'::jsonb,0,'Claims need evidence.','original'),
('127.481.d.3.A',4,'A proposed solution for preventing bone loss is stronger when it is supported by data and a:','["slogan", "model", "rumor", "coin"]'::jsonb,1,'Models and data support solutions.','original'),
('127.481.d.3.B',3,'Students present their findings on muscle fatigue to the class using a poster and clear:','["silence", "jokes only", "explanations", "riddles"]'::jsonb,2,'Communicate findings clearly.','original'),
('127.481.d.3.B',4,'In a lab team, one student records data, one measures, and one reports. Sharing roles is an example of:','["competition", "avoidance", "conflict", "collaboration"]'::jsonb,3,'Teams share work.','original'),
('127.481.d.3.C',3,'When classmates disagree about a result, a respectful scientist uses:','["evidence", "insults", "volume", "rank"]'::jsonb,0,'Evidence settles disputes.','original'),
('127.481.d.3.C',4,'A student disagrees with a lab partner''s conclusion. The best response is to:','["delete the data", "show the data supporting another view", "argue louder", "ignore the partner"]'::jsonb,1,'Evidence-based argument.','original'),
('127.481.d.4.A',3,'To critique an article claiming a miracle bone supplement, a student checks the study''s:','["title length", "font", "evidence and sample size", "cover"]'::jsonb,2,'Critique evidence.','original'),
('127.481.d.4.A',4,'A claim that stretching cures all muscle disease is based on one person''s story. The critique is that it lacks:','["a headline", "a title", "an author", "sufficient evidence"]'::jsonb,3,'One anecdote is weak.','original'),
('127.481.d.4.B',3,'The discovery of X-rays by Wilhelm Roentgen changed medicine by letting doctors see:','["bones inside the body", "a map", "a planet", "the weather"]'::jsonb,0,'X-rays reveal bones.','original'),
('127.481.d.4.B',4,'William Harvey''s work on circulation changed scientific thought by showing that blood:','["is made in the liver and used up", "circulates through the body", "only moves in veins", "is a fixed liquid"]'::jsonb,1,'Harvey described circulation.','original'),
('127.481.d.4.C',3,'A student exploring careers in anatomy could visit a university anatomy lab or a:','["theme park", "shopping mall", "medical museum", "casino"]'::jsonb,2,'Museums and labs provide information.','original'),
('127.481.d.4.C',4,'Professional organizations in health science are helpful to students because they describe training and:','["fashion", "vacations", "cartoons", "career pathways"]'::jsonb,3,'Organizations explain careers.','original'),
('127.481.d.5.A',3,'The six levels of structural organization begin with chemicals and build up through cells, tissues, organs, and organ systems to the:','["organism", "atom", "planet", "species"]'::jsonb,0,'Levels build to the whole organism.','original'),
('127.481.d.5.A',4,'Several tissues working together to perform a specific job form a(n):','["chemical", "organ", "cell", "organism"]'::jsonb,1,'Tissues form organs.','original'),
('127.481.d.5.B',3,'The term proximal means closer to the point of attachment. The elbow is proximal to the:','["chest", "shoulder", "wrist", "neck"]'::jsonb,2,'Proximal is nearer the trunk.','original'),
('127.481.d.5.B',4,'The directional term that means toward the midline of the body is:','["lateral", "distal", "superficial", "medial"]'::jsonb,3,'Medial is toward the midline.','original'),
('127.481.d.5.C',3,'All living organisms respond to stimuli, grow, reproduce, and carry out:','["metabolism", "hibernation", "evaporation", "erosion"]'::jsonb,0,'Metabolism is a life process.','original'),
('127.481.d.5.C',4,'A characteristic of living things is the ability to maintain a stable internal environment, called:','["erosion", "homeostasis", "fatigue", "inflation"]'::jsonb,1,'Homeostasis maintains balance.','original'),
('127.481.d.5.D',3,'A feedback loop that reverses a change and returns the body toward its set point is a:','["blind loop", "positive feedback loop", "negative feedback loop", "broken loop"]'::jsonb,2,'Negative feedback restores balance.','original'),
('127.481.d.5.D',4,'Blood clotting speeds itself up until the bleeding stops, which is an example of:','["negative feedback", "random feedback", "no feedback", "positive feedback"]'::jsonb,3,'Positive feedback amplifies change.','original'),
('127.481.d.5.E',3,'When the body cannot control blood sugar, as in diabetes, the failure to maintain homeostasis can cause:','["disease", "health", "balance", "strength"]'::jsonb,0,'Failure of homeostasis causes disease.','original'),
('127.481.d.5.E',4,'A body that cannot cool itself in extreme heat can develop dangerous overheating, called:','["anemia", "heat stroke", "frostbite", "hypothermia"]'::jsonb,1,'Overheating is a homeostatic failure.','original'),
('127.481.d.6.A',3,'A group of similar cells working together to do a job is called a:','["system", "molecule", "tissue", "organ"]'::jsonb,2,'Tissue is a group of similar cells.','original'),
('127.481.d.6.A',4,'The four primary tissue types are epithelial, connective, muscle, and:','["skeletal", "adipose", "vascular", "nervous"]'::jsonb,3,'Nervous is the fourth type.','original'),
('127.481.d.6.B',3,'Epithelial cells are packed tightly with little space between them, while connective tissue cells are usually spread out in a large amount of:','["extracellular matrix", "empty air", "muscle", "skin"]'::jsonb,0,'Matrix separates connective cells.','original'),
('127.481.d.6.B',4,'Tissue that covers surfaces and lines body cavities has tightly packed cells and is called:','["muscle tissue", "epithelial tissue", "nervous tissue", "connective tissue"]'::jsonb,1,'Epithelium covers and lines.','original'),
('127.481.d.6.C',3,'When skin is cut, cells divide to fill the gap and a clot forms. This process of normal healing is called tissue:','["stress", "loss", "repair", "decay"]'::jsonb,2,'Tissue repair restores structure.','original'),
('127.481.d.6.C',4,'In normal healing, the first stage after a cut is bleeding followed by the formation of a:','["scar only", "bone", "tendon", "blood clot"]'::jsonb,3,'Clotting stops bleeding.','original'),
('127.481.d.6.D',3,'The breakdown of glucose to release energy for cells is part of the metabolism of:','["carbohydrates", "vitamins", "water", "minerals"]'::jsonb,0,'Glucose is a carbohydrate.','original'),
('127.481.d.6.D',4,'Fats are broken down into glycerol and fatty acids, which are the building blocks of:','["sugars", "lipids", "proteins", "nucleic acids"]'::jsonb,1,'Lipids contain fatty acids.','original'),
('127.481.d.7.A',3,'The skull, vertebral column, and rib cage belong to the:','["skin", "muscular system", "axial skeleton", "appendicular skeleton"]'::jsonb,2,'Axial forms the central axis.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_71_v1'
from (values
('127.481.d.7.A',4,'The bones of the arms, legs, shoulders, and hips make up the:','["axial skeleton", "spine", "cranium", "appendicular skeleton"]'::jsonb,3,'Appendicular includes limbs and girdles.','original'),
('127.481.d.7.B',3,'The elbow and knee are examples of joints that move like a door, called:','["hinge joints", "gliding joints", "saddle joints", "pivot joints"]'::jsonb,0,'Hinge joints bend in one plane.','original'),
('127.481.d.7.B',4,'The joint at the top of the neck that allows you to shake your head no is a:','["ball and socket joint", "pivot joint", "gliding joint", "hinge joint"]'::jsonb,1,'Pivot rotates.','original'),
('127.481.d.7.C',3,'The dense, hard outer layer of a bone is called:','["spongy bone", "marrow", "compact bone", "cartilage"]'::jsonb,2,'Compact bone is dense.','original'),
('127.481.d.7.C',4,'The inner, lighter layer of bone with many small spaces that hold red marrow is:','["periosteum", "enamel", "compact bone", "spongy bone"]'::jsonb,3,'Spongy bone is porous.','original'),
('127.481.d.7.D',3,'Besides supporting the body, the skeletal system protects organs such as the brain, which is inside the:','["skull", "femur", "pelvis", "sternum"]'::jsonb,0,'The skull protects the brain.','original'),
('127.481.d.7.D',4,'Red blood cells are produced in the red marrow of bones, which is the blood-forming function of the skeleton called:','["osteoporosis", "hematopoiesis", "ossification", "digestion"]'::jsonb,1,'Hematopoiesis is blood cell production.','original'),
('127.481.d.7.E',3,'The cells that build new bone matrix are:','["osteoclasts", "neurons", "osteoblasts", "osteocytes"]'::jsonb,2,'Blasts build.','original'),
('127.481.d.7.E',4,'The large cells that break down bone tissue so that calcium can be released are:','["osteoblasts", "fibroblasts", "osteocytes", "osteoclasts"]'::jsonb,3,'Clasts break down.','original'),
('127.481.d.7.F',3,'A fracture in which the broken bone pierces through the skin is a:','["compound fracture", "greenstick fracture", "hairline fracture", "simple fracture"]'::jsonb,0,'Open fracture breaks the skin.','original'),
('127.481.d.7.F',4,'A common fracture in children where the bone bends and cracks on one side without breaking completely is a:','["spiral fracture", "greenstick fracture", "comminuted fracture", "compound fracture"]'::jsonb,1,'Soft bones bend.','original'),
('127.481.d.7.G',3,'A disease that makes bones weak and brittle because of a loss of bone density is:','["gout", "scoliosis", "osteoporosis", "arthritis"]'::jsonb,2,'Osteoporosis thins bone.','original'),
('127.481.d.7.G',4,'An abnormal sideways curve of the spine is called:','["osteoporosis", "lordosis", "kyphosis", "scoliosis"]'::jsonb,3,'Scoliosis is a lateral curve.','original'),
('127.481.d.8.A',3,'The outermost layer of the skin is the:','["epidermis", "dermis", "hypodermis", "muscle"]'::jsonb,0,'Epidermis is the surface layer.','original'),
('127.481.d.8.A',4,'The thick layer of skin below the outermost layer, containing blood vessels, nerves, and hair follicles, is the:','["epidermis", "dermis", "cuticle", "fascia"]'::jsonb,1,'Dermis is the deeper layer.','original'),
('127.481.d.8.B',3,'The pigment made by melanocytes that gives skin much of its color is:','["collagen", "hemoglobin", "melanin", "keratin"]'::jsonb,2,'Melanin colors skin.','original'),
('127.481.d.8.B',4,'Besides melanin, skin color can be affected by blood flow, carotene, and exposure to:','["moonlight", "music", "cold water only", "sunlight"]'::jsonb,3,'Sun exposure changes pigment.','original'),
('127.481.d.8.C',3,'When a deep wound heals, collagen fibers form a patch of fibrous connective tissue called a:','["scar", "freckle", "blister", "callus"]'::jsonb,0,'Scar tissue is fibrous.','original'),
('127.481.d.8.C',4,'Deep wounds heal with scar tissue because the dermis cannot be fully replaced with its original:','["pigment only", "structure", "color", "name"]'::jsonb,1,'Scar differs from original tissue.','original'),
('127.481.d.8.D',3,'A bacterial skin infection of hair follicles forming a red, painful bump is a:','["wart", "freckle", "boil", "mole"]'::jsonb,2,'Boils are infected follicles.','original'),
('127.481.d.8.D',4,'The most serious type of skin cancer, which arises from melanocytes, is:','["psoriasis", "eczema", "acne", "melanoma"]'::jsonb,3,'Melanoma is deadly.','original'),
('127.481.d.9.A',3,'The muscular system moves the body, maintains posture, and produces:','["heat", "blood", "bone", "enamel"]'::jsonb,0,'Muscle contraction generates heat.','original'),
('127.481.d.9.A',4,'Shivering when you are cold helps the body maintain its temperature because muscles contracting produce:','["cold", "heat", "bone", "sweat"]'::jsonb,1,'Contractions produce heat.','original'),
('127.481.d.9.B',3,'Muscles move bones by pulling on them through strong cords called:','["ligaments", "veins", "tendons", "nerves"]'::jsonb,2,'Tendons attach muscle to bone.','original'),
('127.481.d.9.B',4,'To bend the arm at the elbow, the biceps contracts while the triceps relaxes. Muscles that work in opposite pairs are called:','["synergists", "agonists only", "fixators", "antagonists"]'::jsonb,3,'Antagonists oppose each other.','original'),
('127.481.d.9.C',3,'Muscle tissue can respond to a nerve signal, which is the characteristic of:','["excitability", "hardness", "coolness", "elasticity only"]'::jsonb,0,'Excitability is responsiveness.','original'),
('127.481.d.9.C',4,'The ability of muscle to shorten forcefully is called:','["excitability", "contractility", "extensibility", "elasticity"]'::jsonb,1,'Contractility is shortening.','original'),
('127.481.d.9.D',3,'Muscle found in the walls of the heart, which is striated and involuntary, is called:','["skeletal muscle", "smooth muscle", "cardiac muscle", "voluntary muscle"]'::jsonb,2,'Cardiac muscle is in the heart.','original'),
('127.481.d.9.D',4,'Muscle in the walls of the intestines that moves food along without conscious control is:','["cardiac muscle", "striated muscle", "skeletal muscle", "smooth muscle"]'::jsonb,3,'Smooth muscle is involuntary.','original'),
('127.481.d.9.E',3,'The smallest contractile unit of a muscle fiber is the:','["sarcomere", "osteon", "tendon", "neuron"]'::jsonb,0,'Sarcomeres contract.','original'),
('127.481.d.9.E',4,'The two main protein filaments in a sarcomere are actin and:','["collagen", "myosin", "insulin", "keratin"]'::jsonb,1,'Actin and myosin slide.','original'),
('127.481.d.9.F',3,'At the neuromuscular junction, a nerve releases the neurotransmitter:','["dopamine only", "adrenaline only", "acetylcholine", "insulin"]'::jsonb,2,'ACh triggers contraction.','original'),
('127.481.d.9.F',4,'For a muscle to contract, calcium is released inside the fiber, allowing myosin to bind to:','["bone", "skin", "blood", "actin"]'::jsonb,3,'Cross bridges form.','original'),
('127.481.d.9.G',3,'The large muscle on the front of the upper arm that bends the elbow is the:','["biceps brachii", "triceps brachii", "deltoid", "gluteus maximus"]'::jsonb,0,'Biceps flex the elbow.','original'),
('127.481.d.9.G',4,'The muscle that covers the shoulder and raises the arm to the side is the:','["gastrocnemius", "deltoid", "trapezius", "pectoralis"]'::jsonb,1,'The deltoid abducts the arm.','original'),
('127.481.d.9.H',3,'A genetic disease that causes progressive muscle weakness is muscular:','["atrophy", "tension", "dystrophy", "fatigue"]'::jsonb,2,'Muscular dystrophy weakens muscles.','original'),
('127.481.d.9.H',4,'A sudden, involuntary muscle contraction that causes pain is called a:','["reflex arc", "fiber", "tendon", "cramp"]'::jsonb,3,'Cramps are spasms.','original'),
('127.481.d.9.I',3,'A force that twists an object around an axis, such as the pull of a muscle on a lever bone, is called:','["torque", "pressure", "friction", "tension"]'::jsonb,0,'Torque is rotational force.','original'),
('127.481.d.9.I',4,'The bones act as levers, the joints as fulcrums, and the muscles provide the:','["base", "effort force", "load", "resistance"]'::jsonb,1,'Muscles supply force.','original'),
('127.481.d.10.A',3,'The nervous system''s job of gathering information from inside and outside the body is its:','["storage function", "digestive function", "sensory function", "motor function"]'::jsonb,2,'Sensory input detects stimuli.','original'),
('127.481.d.10.A',4,'Sending commands from the brain to muscles and glands is the nervous system''s:','["structural function", "integrative function", "sensory function", "motor function"]'::jsonb,3,'Motor output causes responses.','original'),
('127.481.d.10.B',3,'The five traditional senses are sight, hearing, taste, smell, and:','["touch", "thirst", "balance", "pain"]'::jsonb,0,'Touch is the fifth sense.','original'),
('127.481.d.10.B',4,'Sensory receptors convert stimuli into nerve impulses that travel to the:','["skin", "brain", "stomach", "bones"]'::jsonb,1,'Impulses reach the CNS.','original'),
('127.481.d.10.C',3,'Twelve pairs of nerves attached to the brain are the:','["sciatic nerves", "spinal nerves", "cranial nerves", "autonomic nerves"]'::jsonb,2,'Cranial nerves arise from the brain.','original'),
('127.481.d.10.C',4,'Thirty-one pairs of nerves branch off the spinal cord and carry signals to the trunk and limbs. These are the:','["cranial nerves", "vagus nerves", "optic nerves", "spinal nerves"]'::jsonb,3,'Spinal nerves exit the cord.','original'),
('127.481.d.10.D',3,'The colored part of the eye that controls how much light enters is the:','["iris", "cornea", "retina", "lens"]'::jsonb,0,'The iris adjusts the pupil.','original'),
('127.481.d.10.D',4,'The snail-shaped organ of the inner ear that converts sound vibrations into nerve signals is the:','["cornea", "cochlea", "tympanum", "retina"]'::jsonb,1,'The cochlea transduces sound.','original'),
('127.481.d.10.E',3,'The division of the peripheral nervous system that controls voluntary movement of skeletal muscle is the:','["autonomic nervous system", "central nervous system", "somatic nervous system", "enteric system"]'::jsonb,2,'Somatic is voluntary.','original'),
('127.481.d.10.E',4,'The division that regulates involuntary functions such as heart rate and digestion is the:','["somatic nervous system", "central nervous system", "skeletal system", "autonomic nervous system"]'::jsonb,3,'Autonomic is involuntary.','original'),
('127.481.d.10.F',3,'Cells that support and protect neurons rather than carrying impulses are called:','["glial cells", "platelets", "osteocytes", "myocytes"]'::jsonb,0,'Glia support neurons.','original'),
('127.481.d.10.F',4,'In the peripheral nervous system, the glial cells that wrap axons in a myelin sheath are:','["ependymal cells", "Schwann cells", "astrocytes", "microglia"]'::jsonb,1,'Schwann cells myelinate PNS axons.','original'),
('127.481.d.10.G',3,'In the brain, the tissue that appears pale because it contains many myelinated axons is:','["bone", "gray matter", "white matter", "blood"]'::jsonb,2,'Myelin gives a white appearance.','original'),
('127.481.d.10.G',4,'Neuron cell bodies and unmyelinated fibers make up the darker tissue called:','["white matter", "marrow", "cartilage", "gray matter"]'::jsonb,3,'Cell bodies form gray matter.','original'),
('127.481.d.10.H',3,'A neuron that carries impulses from sensory receptors toward the central nervous system is a:','["sensory neuron", "glial cell", "interneuron", "motor neuron"]'::jsonb,0,'Sensory neurons are afferent.','original'),
('127.481.d.10.H',4,'The electrical signal that travels along an axon when a neuron is stimulated enough is called an:','["reflex arc", "action potential", "hormone", "synapse"]'::jsonb,1,'Action potentials carry the signal.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
