       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_71_v1'
from (values
('127.483.d.5.H',3,'A pharmacy follows cleaning standards, such as washing hands for at least 20 seconds and keeping counters:','["cluttered", "dusty", "disinfected", "decorated"]'::jsonb,2,'Clean areas protect patients.','original'),
('127.483.d.5.H',4,'Before compounding a sterile product, the technician cleans the hood with an approved disinfectant such as sterile 70 percent:','["water", "soap bubbles", "vinegar", "isopropyl alcohol"]'::jsonb,3,'Alcohol disinfects surfaces.','original'),
('127.483.d.5.I',3,'A state board of pharmacy licenses pharmacies and pharmacists and also regulates pharmacy:','["technicians", "customers", "tourists", "vendors"]'::jsonb,0,'Boards regulate practice.','original'),
('127.483.d.5.I',4,'A state board of pharmacy can discipline a pharmacist who breaks pharmacy laws, for example by suspending a:','["lunch", "license", "uniform", "parking pass"]'::jsonb,1,'Boards enforce laws.','original'),
('127.483.d.6.A',3,'Medications that can cause serious harm if used wrongly are called high-alert medications, and drugs with names that resemble each other are called:','["expired drugs", "generic drugs only", "look-alike/sound-alike drugs", "fast-acting drugs"]'::jsonb,2,'LASA drugs cause mix-ups.','original'),
('127.483.d.6.A',4,'Hydroxyzine and hydralazine are examples of drugs whose names look and sound similar, which creates a risk of a dispensing:','["benefit", "reward", "discount", "error"]'::jsonb,3,'Similar names cause errors.','original'),
('127.483.d.6.B',3,'Writing part of a drug name in capital letters, such as predniSONE and predniSOLONE, is called:','["Tall Man lettering", "Big Name printing", "Bold naming", "Title casing"]'::jsonb,0,'Tall Man letters highlight differences.','original'),
('127.483.d.6.B',4,'A strategy to prevent errors is to check the drug name, strength, and patient name against the prescription, using at least two:','["colors", "patient identifiers", "coins", "pens"]'::jsonb,1,'Two identifiers prevent errors.','original'),
('127.483.d.6.C',3,'A prescription for an amount of medicine much higher than usual is an example of an abnormal:','["pen", "name", "dose", "label"]'::jsonb,2,'Abnormal doses are flagged.','original'),
('127.483.d.6.C',4,'A refill requested too soon after the last fill, called an early refill, could be a sign of misuse or an:','["discount", "birthday", "sale", "error"]'::jsonb,3,'Early refills prompt review.','original'),
('127.483.d.6.D',3,'A pharmacist has a professional duty to check prescriptions for safety before dispensing. This process is called drug utilization:','["review", "marketing", "decoration", "pricing"]'::jsonb,0,'DUR checks safety.','original'),
('127.483.d.6.D',4,'The pharmacist is responsible for counseling the patient on how to take the medicine and its possible:','["colors", "side effects", "store hours", "costs of parking"]'::jsonb,1,'Counseling is the pharmacist''s role.','original'),
('127.483.d.6.E',3,'A technician notices that a patient''s new prescription is for a drug the patient is already taking. The technician should tell the pharmacist about the possible:','["discount", "sale", "duplication", "birthday"]'::jsonb,2,'Duplicate therapy is flagged.','original'),
('127.483.d.6.E',4,'Noticing a patient who has two different brand names of the same drug in the profile can help the pharmacist prevent an:','["increase in sales", "refund", "new order", "overdose"]'::jsonb,3,'Duplicate ingredients are dangerous.','original'),
('127.483.d.6.F',3,'A pharmacy technician helps keep patients safe by following procedures, double-checking work, and reporting:','["mistakes", "gossip", "rumors", "jokes"]'::jsonb,0,'Report errors.','original'),
('127.483.d.6.F',4,'A culture of safety encourages reporting a near miss, which is an error that was caught before it reached the:','["shelf", "patient", "manager", "supplier"]'::jsonb,1,'Near misses teach lessons.','original'),
('127.483.d.6.G',3,'When a medication error is discovered after a drug has reached a patient, the technician should tell the pharmacist:','["after lunch", "next week", "immediately", "never"]'::jsonb,2,'Prompt reporting protects patients.','original'),
('127.483.d.6.G',4,'After an error, the pharmacy completes an incident report to find out what happened and how to prevent it from happening:','["privately", "quietly", "slowly", "again"]'::jsonb,3,'Reports prevent recurrence.','original'),
('127.483.d.6.H',3,'Basic safety in a pharmacy includes knowing where the fire extinguisher, eyewash station, and emergency:','["exits are", "coupons are", "menus are", "seats are"]'::jsonb,0,'Emergency preparedness.','original'),
('127.483.d.6.H',4,'In an emergency such as a fire or a power outage, the technician follows the pharmacy''s emergency:','["advertisement", "plan", "joke", "menu"]'::jsonb,1,'Plans protect people.','original'),
('127.483.d.7.A',3,'Some medications must be kept in a refrigerator at 36 to 46 degrees Fahrenheit, which is an example of proper storage in regard to:','["price", "size", "temperature", "color"]'::jsonb,2,'Temperature controls stability.','original'),
('127.483.d.7.A',4,'Medicines that are sensitive to light, such as nitroglycerin, are stored in dark amber or opaque containers because light can:','["make them cheaper", "change their label", "make them stronger", "break them down"]'::jsonb,3,'Light degrades drugs.','original'),
('127.483.d.7.B',3,'A list of medications that a hospital or insurance plan has approved for use is a:','["formulary", "recall", "invoice", "catalog"]'::jsonb,0,'A formulary lists preferred drugs.','original'),
('127.483.d.7.B',4,'The purpose of a formulary is to promote safe, effective, and cost-effective choices of:','["uniforms", "medications", "computers", "furniture"]'::jsonb,1,'Formularies guide prescribing.','original'),
('127.483.d.7.C',3,'Taking expired drugs off the shelves and checking dates regularly are procedures of inventory:','["decor", "growth", "control", "trade"]'::jsonb,2,'Inventory control prevents expired stock.','original'),
('127.483.d.7.C',4,'A pharmacy that uses a perpetual inventory system keeps a continuous count of its:','["employees", "windows", "customers", "stock"]'::jsonb,3,'Perpetual inventory tracks stock.','original'),
('127.483.d.7.D',3,'When the pharmacy needs more of a drug, the technician places an order with a drug wholesaler, which is the process of:','["purchasing", "returning", "selling", "expiring"]'::jsonb,0,'Purchasing restocks inventory.','original'),
('127.483.d.7.D',4,'A purchase order for a controlled substance in Schedule II requires a special form called DEA Form:','["444", "222", "22", "1"]'::jsonb,1,'DEA 222 form.','original'),
('127.483.d.7.E',3,'Expired medications that have been removed from stock are typically separated and returned to a company called a reverse:','["customer", "doctor", "distributor", "owner"]'::jsonb,2,'Expired drugs go to reverse distributors.','original'),
('127.483.d.7.E',4,'Expired medications must be clearly marked and stored apart from active stock so they are not accidentally:','["counted", "praised", "cleaned", "dispensed"]'::jsonb,3,'Separate expired drugs.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
